default rel

global main
extern strlen
extern malloc
extern free
extern strstr
extern _setmode
extern _write

%define O_BINARY 0x8000
%define SLOT_LEN 15

section .data
payload_hex db "", 0
slot_token db "__HEX_PAYLOAD__", 0

section .bss
decoded_ptr resq 1
sections resq 7

section .text
main:
    push rbp
    mov rbp, rsp
    sub rsp, 96

    lea rcx, [rel payload_hex]
    call strlen
    mov [rbp-8], rax
    mov rcx, rax
    shr rcx, 1
    mov [rbp-16], rcx
    inc rcx
    call malloc
    test rax, rax
    jz .done
    mov [rel decoded_ptr], rax

    lea r10, [rel payload_hex]
    mov r11, rax
    xor r9, r9
.decode_loop:
    cmp r9, [rbp-16]
    jae .decode_done

    movzx eax, byte [r10 + r9*2]
    cmp al, '9'
    jle .hi_digit
    and al, 0xDF
    sub al, 'A' - 10
    jmp .hi_ready
.hi_digit:
    sub al, '0'
.hi_ready:
    shl al, 4
    mov dl, al

    movzx eax, byte [r10 + r9*2 + 1]
    cmp al, '9'
    jle .lo_digit
    and al, 0xDF
    sub al, 'A' - 10
    jmp .lo_ready
.lo_digit:
    sub al, '0'
.lo_ready:
    or al, dl
    mov [r11 + r9], al
    inc r9
    jmp .decode_loop

.decode_done:
    mov rcx, [rbp-16]
    mov byte [r11 + rcx], 0

    mov [rel sections], r11
    xor ecx, ecx
    mov r10, r11
.split_loop:
    mov al, [r10]
    test al, al
    jz .split_done
    cmp al, 0x1F
    jne .next_char
    mov byte [r10], 0
    inc ecx
    cmp ecx, 7
    jae .next_char
    lea rdx, [r10 + 1]
    lea rax, [rel sections]
    mov [rax + rcx*8], rdx
.next_char:
    inc r10
    jmp .split_loop

.split_done:
    lea rax, [rel sections]
    mov r10, [rax + 8]
    test r10, r10
    jz .cleanup
    mov [rbp-32], r10

    mov rcx, r10
    lea rdx, [rel slot_token]
    call strstr
    test rax, rax
    jz .cleanup
    mov [rbp-24], rax

    mov ecx, 1
    mov edx, O_BINARY
    call _setmode

    mov r10, [rbp-32]
    mov rax, [rbp-24]
    sub rax, r10
    mov ecx, 1
    mov rdx, r10
    mov r8d, eax
    call _write

    lea rcx, [rel payload_hex]
    call strlen
    mov ecx, 1
    lea rdx, [rel payload_hex]
    mov r8d, eax
    call _write

    mov r10, [rbp-24]
    add r10, SLOT_LEN
    mov rcx, r10
    call strlen
    mov ecx, 1
    mov rdx, r10
    mov r8d, eax
    call _write

.cleanup:
    mov rcx, [rel decoded_ptr]
    test rcx, rcx
    jz .done
    call free

.done:
    xor eax, eax
    leave
    ret
